import java.net.*;import java.util.*;import java.util.regex.*;import java.security.SecureRandom;import org.json.*;import org.jsoup.Jsoup;
final class PlaymogoClient {
 static final Set<String> PLAYER_HOSTS=new HashSet<>(Arrays.asList("playmogo.com","doodstream.com","d000d.com","dood.li","do0od.com","doods.pro","d0o0d.com","ds2play.com"));
 static boolean playerUrl(String value){try{URL u=new URL(value);return safeOrigin(u)&&PLAYER_HOSTS.contains(u.getHost())&&u.getPath().matches("/e/(?:[a-z0-9]{12}|[a-z0-9]{32})/?");}catch(Exception e){return false;}}
 static boolean safeOrigin(URL u){return u.getProtocol().equals("https")&&u.getUserInfo()==null&&(u.getPort()==-1||u.getPort()==443)&&u.getQuery()==null&&u.getRef()==null;}
 static String playerPath(URL u){return u.getPath().replaceFirst("/$","");}
 static boolean requestUrl(String value){try{URL u=new URL(value);return playerUrl(value)||(safeOrigin(u)&&u.getHost().equals("playmogo.com")&&u.getPath().matches("/pass_md5/[a-zA-Z0-9-]+/[a-z0-9]{12,64}"));}catch(Exception e){return false;}}
 static void verifyRedirect(String original,String destination)throws Exception{URL a=new URL(original),b=new URL(destination);if(!requestUrl(original)||!requestUrl(destination)||!playerPath(a).equals(playerPath(b))||(!playerUrl(original)&&!a.getHost().equals(b.getHost())))throw new Exception("Playmogo redirect identity mismatch");}
 static void verifyCanonical(String original,String destination)throws Exception{verifyRedirect(original,destination);if(!new URL(destination).getHost().equals("playmogo.com"))throw new Exception("Unverified Playmogo mirror destination");}
 static String handshake(String html)throws Exception{Matcher m=Pattern.compile("/pass_md5/[a-zA-Z0-9-]+/([a-z0-9]{12,64})").matcher(html);if(!m.find())throw new Exception("Playmogo handshake unavailable");String path=m.group(),token=m.group(1);if(!html.contains("?token="+token+"&expiry="))throw new Exception("Playmogo token identity mismatch");return path;}
 static String mediaUrl(String prefix,String token,String suffix,long now)throws Exception{URL url=new URL(prefix);if(!url.getProtocol().equals("https")||url.getUserInfo()!=null||!url.getHost().matches("[a-z0-9-]+\\.cloudatacdn\\.com")||url.getQuery()!=null||url.getPath().length()<2||!token.matches("[a-z0-9]{12,64}")||!suffix.matches("[a-zA-Z0-9]{10}"))throw new Exception("Invalid Playmogo media service");return prefix+suffix+"?token="+token+"&expiry="+now;}
 static void verifyTitle(String title,JSONObject expected)throws Exception{String normalized=NativeCatalog.normalize(title);if(normalized.isEmpty()||normalized.matches(".*\\b(?:deleted|unavailable|removed|not found)\\b.*"))throw new Exception("Playmogo video unavailable");Matcher code=Pattern.compile("(?:^|[^a-z0-9])(?:s0*(\\d+)[ ._-]*)?e(?:p(?:isodul)?)?[ ._-]*0*(\\d+)(?:[^0-9]|$)",Pattern.CASE_INSENSITIVE).matcher(title);if(code.find()&&expected.optInt("episode")>0){int episode=Integer.parseInt(code.group(2));Integer season=code.group(1)==null?null:Integer.parseInt(code.group(1));boolean primary=episode==expected.optInt("episode")&&(season==null||season==expected.optInt("season"));JSONObject verified=expected.optJSONObject("verifiedRequested");boolean mapped=verified!=null&&episode==verified.optInt("episode")&&(season==null||season==verified.optInt("season"));if(!primary&&!mapped)throw new Exception("Playmogo episode identity mismatch");}}
 static boolean enabled(NativeCatalog.Candidate c){if(c.expected==null||!playerUrl(c.embed))return false;if(DozaCatalog.siteUrl(c.page))return true;return NativeCatalog.catalogUrl(c.page)&&c.expected.optBoolean("dfVerified")&&RomanianAudio.declaredRomanian(c.label)&&((c.page.startsWith(NativeCatalog.SITE+"/film/")&&c.expected.optInt("season")==0)||(c.page.startsWith(NativeCatalog.SITE+"/epi/")&&c.expected.optInt("season")>0&&c.expected.optInt("episode")>0));}
 static ResolvedStream resolve(NativeCatalog.Candidate candidate)throws Exception{
  if(!enabled(candidate))throw new Exception("Playmogo site provenance not enabled");PlaymogoHttp.Page page=PlaymogoHttp.get(candidate.embed,candidate.page);verifyCanonical(candidate.embed,page.url);URL actual=new URL(page.url);
  verifyTitle(Jsoup.parse(page.html).title(),candidate.expected);String path=handshake(page.html),token=path.substring(path.lastIndexOf('/')+1);PlaymogoHttp.Page reply=PlaymogoHttp.get(new URL(actual,path).toString(),page.url);if(!new URL(reply.url).getHost().equals(actual.getHost()))throw new Exception("Playmogo handshake redirected to unrelated host");String alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789",suffix="";SecureRandom random=new SecureRandom();for(int i=0;i<10;i++)suffix+=alphabet.charAt(random.nextInt(alphabet.length()));String media=mediaUrl(reply.html.trim(),token,suffix,System.currentTimeMillis()),referer="https://playmogo.com/";
  Map<String,String> headers=new HashMap<>();headers.put("Referer",referer);headers.put("User-Agent",page.userAgent==null?ByseClient.USER_AGENT:page.userAgent);double duration=Mp4Probe.movieDuration(NativeHttp.bytes(media,headers,4096,true));if(duration<90)throw new Exception("Playmogo short/error video rejected");
  return new ResolvedStream("Playmogo",media,referer,candidate.identity(),0,NativeCatalog.catalogUrl(candidate.page)?"DeseneFaine":"DozaAnimata",false,headers);
 }
}
